<script setup lang="ts">
import { computed, shallowRef } from 'vue'
import CharacterPortrait from './CharacterPortrait.vue'
import type { ConnectionPath, ConnectionSubject } from '../types/connections'
const props = defineProps<{ path: ConnectionPath; scope: ConnectionSubject[] }>()
const emit = defineEmits<{ selectStep: [index: number] }>()
const spatial = shallowRef(true), selected = shallowRef<number | null>(null)
const works = computed(() => new Map(props.scope.map(s => [s.subjectId,s.title])))
const nodes = computed(() => props.path.nodes.map(n => ({...n, portrait: { id:n.uid,label:n.name,imageUrl:n.imageUrl,group:'',role:n.kind==='CHARACTER'?'角色':'声优',description:'',portraitSettings:n.portraitSettings,portraitSubjectUid:n.subjectId?'anime:bangumi:'+n.subjectId:undefined }})))
function focus(index: number) { selected.value=index }
</script>
<template><section class="path-stage" aria-label="逐步角色联系"><div class="stage-tools"><strong>{{ path.hopCount }} 步 · {{ path.crossWorkCount }} 次跨作品</strong><button :aria-pressed="spatial" @click="spatial=!spatial">{{ spatial ? '切换二维列表' : '切换空间卡片' }}</button></div>
<ol class="path-chain" :class="{spatial}"><li v-for="(node,index) in nodes" :key="node.uid" :class="{actor:node.kind==='VOICE_ACTOR',focused:selected===index,dimmed:selected!==null&&Math.abs(selected-index)>1}">
  <button class="path-node" :aria-pressed="selected===index" @click="focus(index)"><small>{{ node.kind==='CHARACTER'?'角色':'声优' }}</small><CharacterPortrait :node="node.portrait" large/><strong>{{ node.name }}</strong><span v-if="node.subjectId">{{ works.get(node.subjectId) || '作品 '+node.subjectId }}</span><span v-else>真实配音人员</span></button>
  <button v-if="path.edges[index]" class="path-link" @click="emit('selectStep',index)"><span>{{ path.edges[index]!.fact.kind==='VOICE'?'配音':'剧情关系' }}</span><small>{{ works.get(path.edges[index]!.fact.subjectId) }}</small><span aria-hidden="true">⟶</span><small>第{{ index+1 }}步 · 查看证据</small></button>
</li></ol><p class="stage-note">作品显示在卡片与关系背景中。选择卡片可聚焦相邻步骤，选择关系可核对证据。</p></section></template>
